INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l25',2,4,25,'Do the English speak English?','英国人讲的是英语吗?','并列句与并列连词(主考:and/but/so/or 连接两个简单句 · both A and B 两者都 · either A or B 二者选一 · neither A nor B 两者都不 · not only A but also/as well B 不但…而且)+ the English 群体名词用复数 / at last(辅考)','初到伦敦,火车站又黑又暗;向搬运工问路,自己说得又慢又清楚他却听不懂,他回话又快又含糊——我这才发现:英国人彼此听得懂,我却听不懂他们,他们说的到底是不是英语?','{"q":"Listen and answer — Why does the writer not understand the porter?","options":["The porter spoke neither slowly nor clearly, unlike the teacher''s English","The porter spoke Chinese","The writer was not listening","The porter said nothing at all"],"answer_index":0}'::jsonb,'{"title":"把两个简单句连起来(并列连词)","intro":"本课讲怎么用连词把两个简单句连成并列句:and(和)、but(但)、so(所以)、or(或),还有成对的 both…and、either…or、neither…nor、not only…but also。全用本课句子举例。","table":{"headers":["连词","本课 / 常见例子"],"rows":[["and 顺接 / but 转折 / so 因果 / or 选择","He finished lunch and went into the garden."],["both A and B:两者都","He is both tall and strong."],["either A or B:二者选一;neither A nor B:两者都不","He spoke neither slowly nor clearly."],["not only A but also/as well B:不但…而且","I spoke not only carefully but clearly as well."]]},"specialRules":[{"rule":"the + 形容词(the English / the rich)指一个群体,动词用复数:The English like tea.","mark":"the + 形容词"},{"rule":"at last = 终于、最后:I arrived in London at last.","mark":"at last"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',1,NULL,'I arrived in London at last. The train station was big, black, and dark.','我终于到了伦敦。火车站又大又黑又暗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',2,NULL,'I did not know the way to my hotel, so I asked a porter.','我不知道去饭店的路怎么走,于是向一个搬运工打听。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',3,NULL,'I not only spoke English very carefully, but very clearly as well.','我的英语讲得不但非常认真,而且咬字也非常清楚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',4,NULL,'The porter, however, could not understand me.','然而搬运工却不明白我的话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',5,NULL,'I repeated my question several times, and at last he understood.','我把问话重复了很多遍,他终于听懂了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',6,NULL,'He answered me, but he spoke neither slowly nor clearly.','他回答了我,但他讲得既不慢也不清楚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',7,NULL,'''I am a foreigner,'' I said. Then he spoke slowly, but I could not understand him.','"我是个外国人,"我说。于是他说得慢了,可我还是听不懂。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',8,NULL,'My teacher never spoke English like that! The porter and I looked at each other and smiled.','我的老师从来不那样讲英语!我和搬运工相视一笑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',9,NULL,'Then he said something and I understood it. ''You''ll soon learn English!'' he said.','接着,他说了点什么,这回我听懂了。"您会很快学会英语的!"他说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l25',10,NULL,'The English understand each other, but I don''t understand them! Do they speak English?','英国人之间相互听得懂,可我却不懂他们的话!他们说的是英语吗?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
