INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l25','train station','railway station','火车站;美语 train station,英式 railway station') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
